bist_esp_err_t bist_cpu_stack_overflow_init(void)
{
    /*
     * Fill the entire protection region with the sentinel pattern.
     * A single-word sentinel can fall in an unwritten gap between
     * stack frames (saved regs + padding occupy ~32 bytes per 160-byte
     * frame), making single-point detection unreliable. Filling the
     * full region guarantees at least one word lands in a zeroed buffer.
     */
    uint32_t *p   = (uint32_t *)&_stack_overflow_protection_end;
    uint32_t *end = (uint32_t *)&_stack_overflow_protection_start;
    for (; p <= end; p++) {
        *p = STACK_PROTECTION_PATTERN;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_cpu_stack_overflow_check(void)
{
    uint32_t *p   = (uint32_t *)&_stack_overflow_protection_end;
    uint32_t *end = (uint32_t *)&_stack_overflow_protection_start;
    for (; p <= end; p++) {
        if (*p != STACK_PROTECTION_PATTERN) {
            handle_stack_overflow();
            return BIST_ESP_STACK_TEST_OVERFLOW;
        }
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_cpu_stack_overflow_test(void)
{
    volatile int count_max = 20000;

    bist_cpu_stack_overflow_init();

    BIST_ADD_LABEL("bist_cpu_stack_overflow_data");
    for (int k = 0; k < count_max; k++) {
        /* intentionally cause a stack overflow */
        bist_cpu_stack_recursive(k);

        if (bist_cpu_stack_overflow_check() == BIST_ESP_STACK_TEST_OVERFLOW) {
            return BIST_ESP_OK;
        }
    }

    return BIST_ESP_STACK_TEST_ERR;
}

uint32_t bist_get_stack_high_watermark(void)
{
    uint32_t *stack_top = (uint32_t *)&_stack_top;
    uint32_t *stack_bottom = (uint32_t *)&_stack_overflow_protection_start;
    uint32_t high_watermark = 0;

    /* We should check after the overflow protection region */
    stack_bottom++;

    for (uint32_t *p = stack_bottom; p < stack_top; p++) {
        if (*p == STACK_FILL_PATTERN) {
            high_watermark++;
        } else {
            break;
        }
    }

    return high_watermark * sizeof(uint32_t);
}

static void bist_hw_interrupt_check_ratio(void)
{
    uint32_t expected = 2 * hw_interrupt_count_2;
    uint32_t diff = (hw_interrupt_count_1 > expected)
                    ? (hw_interrupt_count_1 - expected)
                    : (expected - hw_interrupt_count_1);
    if (diff > 1U) {
        hw_interrupt_test_failed = true;
    }
}

static void bist_hw_timer_ack(bist_hw_timer_t *timer)
{
    uint32_t event = TIMER_LL_EVENT_ALARM(timer->timer_id);

    if (timer_ll_get_intr_status(timer->hal.dev) & event) {
        timer_ll_clear_intr_status(timer->hal.dev, event);
        /* Alarm auto-disables in hardware; re-arm for periodic mode. */
        timer_ll_enable_alarm(timer->hal.dev, timer->timer_id, true);
    }
}

static void bist_hw_timer0_isr(void *arg)
{
    bist_hw_timer_t *timer = (bist_hw_timer_t *)arg;
    bist_hw_timer_ack(timer);
    hw_interrupt_count_1++;
}

static void bist_hw_timer1_isr(void *arg)
{
    bist_hw_timer_t *timer = (bist_hw_timer_t *)arg;
    bist_hw_timer_ack(timer);
    hw_interrupt_count_2++;
    hw_check_divider++;
    if (hw_check_divider >= BIST_HW_CHECK_EVERY_N) {
        hw_check_divider = 0;
        bist_hw_interrupt_check_ratio();
    }
}

static bist_esp_err_t bist_hw_timer_start(bist_hw_timer_t *timer)
{
    const uint32_t core_id = esp_cpu_get_core_id();
    const uint32_t divider = CONFIG_XTAL_FREQ; /* XTAL_MHz -> 1 MHz (1 tick = 1 us) */
    const uint32_t cpu_intr_mask = 1U << timer->cpu_intr;
    esp_cpu_intr_handler_t isr = (timer->group_id == 0) ? bist_hw_timer0_isr : bist_hw_timer1_isr;

    if (divider < 2U) {
        ESP_LOGE(TAG, "Invalid XTAL divider %u", (unsigned)divider);
        return BIST_ESP_INTERRUPT_TEST_ERR;
    }

#ifdef __PERIPH_CTRL_ALLOW_LEGACY_API
    periph_module_enable((timer->group_id == 0) ? PERIPH_TIMG0_MODULE : PERIPH_TIMG1_MODULE);
#else
    /* Avoid resetting the group: TIMG0 may already host MWDT. */
    _timg_ll_enable_bus_clock(timer->group_id, true);
#endif

    timer_hal_init(&timer->hal, timer->group_id, timer->timer_id);

    PERIPH_RCC_ATOMIC() {
        timer_ll_enable_clock(timer->group_id, timer->timer_id, true);
        timer_ll_set_clock_source(timer->group_id, timer->timer_id, GPTIMER_CLK_SRC_XTAL);
    }
    timer_ll_set_clock_prescale(timer->hal.dev, timer->timer_id, divider);
    timer_ll_set_count_direction(timer->hal.dev, timer->timer_id, GPTIMER_COUNT_UP);
    timer_ll_enable_auto_reload(timer->hal.dev, timer->timer_id, true);
    timer_ll_set_reload_value(timer->hal.dev, timer->timer_id, 0);
    timer_hal_set_counter_value(&timer->hal, 0);
    timer_ll_set_alarm_value(timer->hal.dev, timer->timer_id, timer->period_us);
    timer_ll_enable_intr(timer->hal.dev, TIMER_LL_EVENT_ALARM(timer->timer_id), false);
    timer_ll_clear_intr_status(timer->hal.dev, TIMER_LL_EVENT_ALARM(timer->timer_id));

    esp_cpu_intr_disable(cpu_intr_mask);
    esp_rom_route_intr_matrix(core_id, timer->intr_source, timer->cpu_intr);
    esp_cpu_intr_set_type(timer->cpu_intr, ESP_CPU_INTR_TYPE_LEVEL);
    esp_cpu_intr_set_priority(timer->cpu_intr, SOC_INTERRUPT_LEVEL_MEDIUM);
    esp_cpu_intr_set_handler(timer->cpu_intr, isr, timer);
    esp_cpu_intr_enable(cpu_intr_mask);

    timer_ll_enable_intr(timer->hal.dev, TIMER_LL_EVENT_ALARM(timer->timer_id), true);
    timer_ll_enable_alarm(timer->hal.dev, timer->timer_id, true);
    timer_ll_enable_counter(timer->hal.dev, timer->timer_id, true);

    ESP_LOGD(TAG, "TIMG%d T%d period %u us -> CPU intr %d",
             timer->group_id, (int)timer->timer_id, (unsigned)timer->period_us, timer->cpu_intr);
    return BIST_ESP_OK;
}

static void bist_hw_timer_deinit(bist_hw_timer_t *timer)
{
    const uint32_t cpu_intr_mask = 1U << timer->cpu_intr;

    if (timer->hal.dev == NULL) {
        return;
    }

    timer_ll_enable_counter(timer->hal.dev, timer->timer_id, false);
    timer_ll_enable_alarm(timer->hal.dev, timer->timer_id, false);
    timer_ll_clear_intr_status(timer->hal.dev, TIMER_LL_EVENT_ALARM(timer->timer_id));
    timer_ll_enable_intr(timer->hal.dev, TIMER_LL_EVENT_ALARM(timer->timer_id), false);
    esp_cpu_intr_disable(cpu_intr_mask);
    esp_rom_route_intr_matrix(esp_cpu_get_core_id(), timer->intr_source, ETS_INVALID_INUM);
    timer_hal_deinit(&timer->hal);
}

static void bist_hw_timers_deinit(void)
{
    for (int i = 0; i < BIST_HW_TIMER_COUNT; i++) {
        bist_hw_timer_deinit(&hw_timers[i]);
    }
}

static bist_esp_err_t bist_hardware_interrupt_test_init(void)
{
    bist_esp_err_t ret;
    hw_check_divider = 0;
    hw_interrupt_count_1 = 0;
    hw_interrupt_count_2 = 0;
    hw_interrupt_test_failed = false;

    hw_timers[0] = (bist_hw_timer_t) {
        .group_id = 0,
        .cpu_intr = BIST_HW_TIMER_CPU_INTR_0,
        .timer_id = 0,
        .intr_source = soc_timg_gptimer_signals[0][0].irq_id,
        .period_us = BIST_HARDWARE_INTERRUPT_PERIOD_US_1,
    };
    hw_timers[1] = (bist_hw_timer_t) {
        .group_id = 1,
        .cpu_intr = BIST_HW_TIMER_CPU_INTR_1,
        .timer_id = 0,
        .intr_source = soc_timg_gptimer_signals[1][0].irq_id,
        .period_us = BIST_HARDWARE_INTERRUPT_PERIOD_US_2,
    };

    for (int i = 0; i < BIST_HW_TIMER_COUNT; i++) {
        ret = bist_hw_timer_start(&hw_timers[i]);
        if (ret != BIST_ESP_OK) {
            ESP_LOGE(TAG, "Failed to start TIMG hardware timer %d", i);
            bist_hw_timers_deinit();
            return BIST_ESP_INTERRUPT_TEST_ERR;
        }
    }

    ESP_LOGD(TAG, "Hardware interrupt setup complete: TIMG0/TIMG1, periods %u/%u us",
             (unsigned)BIST_HARDWARE_INTERRUPT_PERIOD_US_1,
             (unsigned)BIST_HARDWARE_INTERRUPT_PERIOD_US_2);

    return BIST_ESP_OK;
}

bist_esp_err_t bist_hardware_interrupt_test(void)
{
    int ret = BIST_ESP_OK;

    ret = bist_hardware_interrupt_test_init();
    if (ret != BIST_ESP_OK) {
        ESP_LOGE(TAG, "Failed to initialize hardware interrupt test");
        return BIST_ESP_INTERRUPT_TEST_ERR;
    }

    do {
        esp_rom_delay_us(10);
        if (hw_interrupt_test_failed) {
            break;
        }
    } while (hw_interrupt_count_1 < 1000 && hw_interrupt_count_2 < 1000);

    bist_hw_timers_deinit();

    if (hw_interrupt_test_failed) {
        ESP_LOGE(TAG, "Hardware interrupt test failed: cnt1 %d, cnt2 %d",
                 hw_interrupt_count_1, hw_interrupt_count_2);
        return BIST_ESP_INTERRUPT_TEST_ERR;
    }

    return BIST_ESP_OK;
}

static void bist_interrupt_callback(void *arg)
{
    REG_WRITE((uint32_t)arg, 0U);
    interrupt_count++;
}

bist_esp_err_t bist_interrupt_source_map_test(void)
{
    const uint32_t core_id = esp_cpu_get_core_id();
    const uint32_t cpu_intr_mask = 1U << BIST_INTERRUPT_CPU_NUMBER;
    uint32_t intr_enabled_mask = 0x0;

    /* Keep the CPU interrupt disabled while sweeping sources so a pending
     * peripheral IRQ cannot fire while briefly routed to this line. */
    esp_cpu_intr_disable(cpu_intr_mask);
    esp_cpu_intr_set_type(BIST_INTERRUPT_CPU_NUMBER, ESP_CPU_INTR_TYPE_LEVEL);
    esp_cpu_intr_set_priority(BIST_INTERRUPT_CPU_NUMBER, SOC_INTERRUPT_LEVEL_MEDIUM);

    for (int src = 0; src < BIST_INTERRUPT_SOURCE_COUNT; src++) {
        ESP_LOGD(TAG, "Mapping interrupt source %d", src);
        interrupt_count = 0;
        bool error = false;
        uint32_t source = test_interrupt_sources[src].source;
        uint32_t reg = test_interrupt_sources[src].reg;

        esp_rom_route_intr_matrix(core_id, source, BIST_INTERRUPT_CPU_NUMBER);
        esp_cpu_intr_set_handler(BIST_INTERRUPT_CPU_NUMBER, bist_interrupt_callback, (void *)reg);
        esp_cpu_intr_enable(cpu_intr_mask);

        for (int i = 0; i < BIST_INTERRUPT_LOOP_COUNT; ++i) {
            REG_WRITE(reg, BIT(0));
            esp_rom_delay_us(100);
        }
        BIST_ADD_LABEL("bist_interrupt_source_map_count");

        intr_enabled_mask = esp_cpu_intr_get_enabled_mask();
        if (!(intr_enabled_mask & cpu_intr_mask)) {
            ESP_LOGE(TAG, "Enabled interrupts mismatch: expect bit %d set, got 0x%lx", BIST_INTERRUPT_CPU_NUMBER, intr_enabled_mask);
            error = true;
        }

        esp_cpu_intr_disable(cpu_intr_mask);

        /* Unmap the interrupt source */
        esp_rom_route_intr_matrix(core_id, source, ETS_INVALID_INUM);

        if (error) {
            return BIST_ESP_INTERRUPT_TEST_ERR;
        }

        intr_enabled_mask = esp_cpu_intr_get_enabled_mask();
        if (intr_enabled_mask & cpu_intr_mask) {
            ESP_LOGE(TAG, "Enabled interrupts mismatch: expect bit %d unset, got 0x%lx", BIST_INTERRUPT_CPU_NUMBER, intr_enabled_mask);
            return BIST_ESP_INTERRUPT_TEST_ERR;
        }

        if (interrupt_count != BIST_INTERRUPT_LOOP_COUNT) {
            ESP_LOGE(TAG, "Interrupt count mismatch (%d): %d != %d", src, interrupt_count, BIST_INTERRUPT_LOOP_COUNT);
            return BIST_ESP_INTERRUPT_TEST_ERR;
        }
        ESP_LOGD(TAG, "Interrupt source %d mapped to CPU interrupt %d -- count: %d == %d", src, BIST_INTERRUPT_CPU_NUMBER, interrupt_count, BIST_INTERRUPT_LOOP_COUNT);
    }

    ESP_LOGD(TAG, "Software IRQ sources successfully triggered CPU interrupt %d", BIST_INTERRUPT_CPU_NUMBER);
    return BIST_ESP_OK;
}

uint32_t calculate_crc32(uint8_t *data, size_t length)
{
    uint32_t calc_crc = 0;
    size_t processed = 0;

    while (processed < length) {
        size_t chunk_size = length - processed;
        if (chunk_size > CONFIG_BIST_FLASH_TEST_CHUNK_SIZE) {
            chunk_size = CONFIG_BIST_FLASH_TEST_CHUNK_SIZE;
        }

        calc_crc = bist_hd_crc32_update(data + processed, chunk_size, calc_crc);
        processed += chunk_size;
    }

    return calc_crc & 0xFFFFFFFF;
}

bist_esp_err_t bist_flash_test(void)
{
    uint32_t crc_data, crc_text = 0;
    volatile size_t crc_section_len = 0;

    ESP_LOGD(TAG, "Flash text CRC addr: %p", &_crc_section_text_start);
    ESP_LOGD(TAG, "flash.text CRC: 0x%lx", _crc_section_text_start);
    ESP_LOGD(TAG, "Flash data CRC addr: %p", &_crc_section_data_start);
    ESP_LOGD(TAG, "flash.rodata CRC: 0x%lx", _crc_section_data_start);

    ESP_LOGD(TAG, "Calculating CRC for flash.rodata section from %p to %p (%d B)", &_flash_rodata_start,
             &_flash_rodata_end, (size_t)(&_flash_rodata_end - &_flash_rodata_start) * 4);

    crc_section_len = (size_t)(&_flash_rodata_end - &_flash_rodata_start) * 4;
    BIST_ADD_LABEL("bist_flash_test_data");
    crc_data = calculate_crc32((uint8_t *)&_flash_rodata_start, crc_section_len);

    ESP_LOGD(TAG, "Calculated CRC for flash.rodata section: 0x%lx", crc_data);
    if (crc_data != _crc_section_data_start) {
        ESP_LOGE(TAG, "CRC for flash.rodata section does not match the expected value");
        return BIST_ESP_FLASH_TEST_ERR;
    }

    ESP_LOGD(TAG, "Calculating CRC for flash.text section from %p to %p (%d B)", &_flash_text_start,
             &_flash_text_end, (size_t)(&_flash_text_end - &_flash_text_start) * 4);

    crc_section_len = (size_t)(&_flash_text_end - &_flash_text_start) * 4;
    BIST_ADD_LABEL("bist_flash_test_text");
    crc_text = calculate_crc32((uint8_t *)&_flash_text_start, crc_section_len);
    ESP_LOGD(TAG, "Calculated CRC for flash.text section: 0x%lx", crc_text);
    if (crc_text != _crc_section_text_start) {
        ESP_LOGE(TAG, "CRC for flash.text section does not match the expected value");
        return BIST_ESP_FLASH_TEST_ERR;
    }

    return BIST_ESP_OK;
}

static uint32_t bist_ram_test_words(void)
{
    return ((uint32_t)&_bist_ram_test_end - (uint32_t)&_bist_ram_test_start) / 4u;
}

