{
    return run_on_safe_stack(march_a_impl);
}

bist_esp_err_t bist_ram_test_march_x(void)
{
    return run_on_safe_stack(march_x_impl);
}

static void abraham_advance_pair(size_t num_partitions)
{
    if (num_partitions <= 1) {
        return;
    }
    abraham_pair_j++;
    if (abraham_pair_j >= num_partitions) {
        abraham_pair_i++;
        abraham_pair_j = abraham_pair_i + 1;
    }
    if (abraham_pair_i >= num_partitions - 1) {
        abraham_pair_i = 0;
        abraham_pair_j = 1;
    }
}

bist_esp_err_t bist_ram_test_abraham(void)
{
    bist_esp_err_t result = run_on_safe_stack(abraham_impl);
    volatile uint32_t dram_test_size = bist_ram_test_words();
    size_t num_partitions = (dram_test_size + BIST_ESP_RAM_BACKUP_CHUNK_SIZE - 1)
                            / BIST_ESP_RAM_BACKUP_CHUNK_SIZE;
    abraham_advance_pair(num_partitions);
    return result;
}

void bist_ram_test_abraham_reset(void)
{
    abraham_pair_i = 0;
    abraham_pair_j = 1;
}

bist_esp_err_t bist_ram_test_abraham_full(void)
{
    volatile uint32_t dram_test_size = bist_ram_test_words();
    size_t num_partitions = (dram_test_size + BIST_ESP_RAM_BACKUP_CHUNK_SIZE - 1)
                            / BIST_ESP_RAM_BACKUP_CHUNK_SIZE;
    size_t total_pairs = (num_partitions <= 1)
                         ? 1
                         : (num_partitions * (num_partitions - 1)) / 2;

    bist_ram_test_abraham_reset();

    for (size_t p = 0; p < total_pairs; p++) {
        bist_esp_err_t err = run_on_safe_stack(abraham_impl);
        if (err != BIST_ESP_OK) {
            return err;
        }
        abraham_advance_pair(num_partitions);
    }
    return BIST_ESP_OK;
}

static void test_callback(void *arg)
{
    test_failed = true;
}

bist_esp_err_t bist_ext_crystal_fail_test(void)
{
#if SOC_XT_WDT_SUPPORTED
    esp_err_t err;

    esp_xt_wdt_config_t cfg = {
        .timeout = 200,
        .auto_backup_clk_enable = false,
    };

    esp_xt_wdt_register_callback(test_callback, NULL);

    err = esp_xt_wdt_init(&cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Failed to initialize external watchdog timer");
        return BIST_ESP_CLOCK_TEST_ERR;
    }

    ets_delay_us(2000);

    if (test_failed) {
        test_failed = false;
        return BIST_ESP_CLOCK_TEST_ERR;
    }

#else
    /* SoCs without XT WDT have no hardware to detect 32k crystal
     * failure; skip this test and report OK. */
    ESP_LOGD(TAG, "SoCs without XT WDT have no hardware to detect 32k crystal failure; skipping test.");
#endif

    return BIST_ESP_OK;
}

bist_esp_err_t bist_main_crystal_test(void)
{
    uint32_t xtal_freq_mhz = rtc_clk_xtal_freq_get();
    uint32_t expected_xtal_freq = xtal_freq_mhz * MHZ;

    /*
     * rtc_clk_cal returns the 32K XTAL clock period in fixed-point format (Q13.19).
     * If the main XTAL drifts, the returned value shifts proportionally.
     */
    uint32_t cal_val = rtc_clk_cal(CLK_CAL_32K_XTAL, 500);
    if (cal_val == 0) {
        return BIST_ESP_CLOCK_TEST_ERR;
    }

    /*
     * Derive actual XTAL frequency from the calibration result:
     */
    uint32_t xtal_freq = (uint32_t)(((uint64_t)cal_val * xtal_freq_mhz * 32768) >> RTC_CLK_CAL_FRACT);
    float deviation = fabs((float)(int)(xtal_freq - expected_xtal_freq)) / expected_xtal_freq * 100;

    /*
     * Check if the calculated XTAL frequency is within
     * CONFIG_ESP_BIST_CLOCK_PERCENT_FREQUENCY_DRIFT
     */
    if (deviation > CONFIG_ESP_BIST_CLOCK_PERCENT_FREQUENCY_DRIFT) {
        return BIST_ESP_CLOCK_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_wdt_test(void)
{
    volatile uint32_t wdt_timeout_us = 10000;
    soc_reset_reason_t reset = esp_rom_get_reset_reason(0);

    if (reset == RESET_REASON_CORE) {
        return BIST_ESP_OK;
    }

    BIST_ADD_LABEL("bist_test_wdt_timeout");

    wdt_init(wdt_timeout_us);

    /* let watchdog callback happen or timeout */
    ets_delay_us(50000);

    wdt_deinit();

    return BIST_ESP_WDT_TEST_ERR;
}

static bist_esp_err_t bist_adc_set_pin_pull(adc_unit_t unit, adc_channel_t channel,
                                            gpio_pull_mode_t pull, int *io_num)
{
    if (adc_oneshot_channel_to_io(unit, channel, io_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to map ADC%d channel %d to GPIO", unit + 1, channel);
        return BIST_ESP_ADC_TEST_ERR;
    }

    if (gpio_set_pull_mode(*io_num, pull) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d pull mode", *io_num);
        return BIST_ESP_ADC_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_adc_low_level_test(adc_unit_t unit, adc_channel_t channel)
{
    adc_oneshot_unit_handle_t adc_handle = NULL;
    int io_num = 0;
    int raw = 0;
    bist_esp_err_t ret = BIST_ESP_ADC_TEST_ERR;

    adc_oneshot_unit_init_cfg_t init_config = {
        .unit_id = unit,
    };
    if (adc_oneshot_new_unit(&init_config, &adc_handle) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to create ADC%d unit", unit + 1);
        return BIST_ESP_ADC_TEST_ERR;
    }

    adc_oneshot_chan_cfg_t config = {
        .atten = ADC_ATTEN_DB_12,
        .bitwidth = ADC_BITWIDTH_DEFAULT,
    };
    if (adc_oneshot_config_channel(adc_handle, channel, &config) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to configure ADC%d channel %d", unit + 1, channel);
        adc_oneshot_del_unit(adc_handle);
        return BIST_ESP_ADC_TEST_ERR;
    }

    if (bist_adc_set_pin_pull(unit, channel, GPIO_PULLDOWN_ONLY, &io_num) != BIST_ESP_OK) {
        adc_oneshot_del_unit(adc_handle);
        return BIST_ESP_ADC_TEST_ERR;
    }

    ets_delay_us(10000);

    if (adc_oneshot_read(adc_handle, channel, &raw) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to read ADC%d channel %d", unit + 1, channel);
        goto cleanup;
    }

    ESP_LOGI(TAG, "ADC%d channel %d low raw: %d", unit + 1, channel, raw);

    if (raw > BIST_ADC_TOLERANCE) {
        ESP_LOGE(TAG, "ADC%d channel %d low test failed, raw: %d, expected: 0",
                 unit + 1, channel, raw);
        goto cleanup;
    }

    ret = BIST_ESP_OK;

cleanup:
    gpio_reset_pin(io_num);
    adc_oneshot_del_unit(adc_handle);
    return ret;
}

