bist_esp_err_t bist_adc_reference_test(adc_unit_t unit, adc_channel_t channel)
{
    if (unit >= SOC_ADC_PERIPH_NUM) {
        ESP_LOGE(TAG, "ADC unit error: %d", unit);
        return BIST_ESP_ADC_TEST_ERR;
    }

    if (channel >= SOC_ADC_CHANNEL_NUM(unit)) {
        ESP_LOGE(TAG, "ADC channel error: %d", channel);
        return BIST_ESP_ADC_TEST_ERR;
    }

    adc_oneshot_unit_handle_t adc_handle = NULL;
    int io_num = 0;
    int raw = 0;
    bist_esp_err_t ret = BIST_ESP_ADC_TEST_ERR;

    adc_oneshot_unit_init_cfg_t init_config = {
        .unit_id = unit,
    };
    if (adc_oneshot_new_unit(&init_config, &adc_handle) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to create ADC%d unit", unit + 1);
        return BIST_ESP_ADC_TEST_ERR;
    }

    adc_oneshot_chan_cfg_t config = {
        .atten = ADC_ATTEN_DB_12,
        .bitwidth = ADC_BITWIDTH_DEFAULT,
    };
    if (adc_oneshot_config_channel(adc_handle, channel, &config) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to configure ADC%d channel %d", unit + 1, channel);
        adc_oneshot_del_unit(adc_handle);
        return BIST_ESP_ADC_TEST_ERR;
    }

    adc_ll_vref_output(unit, channel, true);

    ets_delay_us(10000);

    if (adc_oneshot_read(adc_handle, channel, &raw) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to read ADC%d channel %d", unit + 1, channel);
        goto cleanup;
    }

    ESP_LOGD(TAG, "ADC%d channel %d reference raw: %d", unit + 1, channel, raw);

    if (raw < (BIST_ADC_REFERENCE - BIST_ADC_TOLERANCE) || raw > (BIST_ADC_REFERENCE + BIST_ADC_TOLERANCE)) {
        ESP_LOGE(TAG, "ADC%d channel %d reference test failed, raw stuck low: %d, expected: %d",
                 unit + 1, channel, raw, BIST_ADC_REFERENCE);
        goto cleanup;
    }

    ret = BIST_ESP_OK;

cleanup:
    gpio_reset_pin(io_num);
    adc_oneshot_del_unit(adc_handle);

    return ret;
}

static bist_esp_err_t bist_gpio_set_and_check_level(gpio_num_t gpio_num, int set_level)
{
    if (gpio_set_level(gpio_num, set_level) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d to %d", gpio_num, set_level);
        return BIST_ESP_IO_TEST_ERR;
    }

    int level = gpio_get_level(gpio_num);

    if (level != set_level) {
        ESP_LOGE(TAG, "GPIO %d output test failed, expected level: %d, got: %d", gpio_num, set_level, level);
        return BIST_ESP_IO_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_gpio_output_test(gpio_num_t gpio_num)
{
    if (!GPIO_IS_VALID_GPIO(gpio_num)) {
        ESP_LOGE(TAG, "GPIO number error: %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_set_direction(gpio_num, GPIO_MODE_INPUT_OUTPUT) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d as output", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (bist_gpio_set_and_check_level(gpio_num, 0) != BIST_ESP_OK) {
        return BIST_ESP_IO_TEST_ERR;
    }

    if (bist_gpio_set_and_check_level(gpio_num, 1) != BIST_ESP_OK) {
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_gpio_input_test(gpio_num_t gpio_num, bool expected_level)
{
    if (!GPIO_IS_VALID_GPIO(gpio_num)) {
        ESP_LOGE(TAG, "GPIO number error: %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_set_direction(gpio_num, GPIO_MODE_INPUT) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d as input", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_get_level(gpio_num) != expected_level) {
        ESP_LOGE(TAG, "GPIO input test failed for GPIO %d, expected level: %d", gpio_num, expected_level);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    return BIST_ESP_OK;
}

