esp_err_t gpio_set_pull_mode(gpio_num_t gpio_num, gpio_pull_mode_t pull)
{
    GPIO_CHECK(GPIO_IS_VALID_GPIO(gpio_num), "GPIO number error", ESP_ERR_INVALID_ARG);
    GPIO_CHECK(pull <= GPIO_FLOATING, "GPIO pull mode error", ESP_ERR_INVALID_ARG);
    esp_err_t ret = ESP_OK;

    switch (pull) {
    case GPIO_PULLUP_ONLY:
        gpio_pulldown_dis(gpio_num);
        gpio_pullup_en(gpio_num);
        break;

    case GPIO_PULLDOWN_ONLY:
        gpio_pulldown_en(gpio_num);
        gpio_pullup_dis(gpio_num);
        break;

    case GPIO_PULLUP_PULLDOWN:
        gpio_pulldown_en(gpio_num);
        gpio_pullup_en(gpio_num);
        break;

    case GPIO_FLOATING:
        gpio_pulldown_dis(gpio_num);
        gpio_pullup_dis(gpio_num);
        break;

    default:
        ESP_LOGE(GPIO_TAG, "Unknown pull up/down mode,gpio_num=%u,pull=%u", gpio_num, pull);
        ret = ESP_ERR_INVALID_ARG;
        break;
    }

    return ret;
}

esp_err_t gpio_set_direction(gpio_num_t gpio_num, gpio_mode_t mode)
{
    GPIO_CHECK(GPIO_IS_VALID_GPIO(gpio_num), "GPIO number error", ESP_ERR_INVALID_ARG);

    if ((GPIO_IS_VALID_OUTPUT_GPIO(gpio_num) != true) && (mode & GPIO_MODE_DEF_OUTPUT)) {
        ESP_LOGE(GPIO_TAG, "io_num=%d can only be input", gpio_num);
        return ESP_ERR_INVALID_ARG;
    }

    esp_err_t ret = ESP_OK;

    if (mode & GPIO_MODE_DEF_INPUT) {
        gpio_input_enable(gpio_num);
    } else {
        gpio_input_disable(gpio_num);
    }

    if (mode & GPIO_MODE_DEF_OUTPUT) {
        gpio_output_enable(gpio_num);
    } else {
        gpio_output_disable(gpio_num);
    }

    if (mode & GPIO_MODE_DEF_OD) {
        gpio_od_enable(gpio_num);
    } else {
        gpio_od_disable(gpio_num);
    }

    return ret;
}

esp_err_t gpio_config(const gpio_config_t *pGPIOConfig)
{
    uint64_t gpio_pin_mask = (pGPIOConfig->pin_bit_mask);
    uint32_t io_num = 0;
    uint8_t input_en = 0;
    uint8_t output_en = 0;
    uint8_t od_en = 0;
    uint8_t pu_en = 0;
    uint8_t pd_en = 0;

    if (pGPIOConfig->pin_bit_mask == 0 || pGPIOConfig->pin_bit_mask & ~SOC_GPIO_VALID_GPIO_MASK) {
        ESP_LOGE(GPIO_TAG, "GPIO_PIN mask error ");
        return ESP_ERR_INVALID_ARG;
    }

    if (pGPIOConfig->mode & GPIO_MODE_DEF_OUTPUT && pGPIOConfig->pin_bit_mask & ~SOC_GPIO_VALID_OUTPUT_GPIO_MASK) {
        ESP_LOGE(GPIO_TAG, "GPIO can only be used as input mode");
        return ESP_ERR_INVALID_ARG;
    }

    do {
        if (((gpio_pin_mask >> io_num) & BIT(0))) {

            if ((pGPIOConfig->mode) & GPIO_MODE_DEF_INPUT) {
                input_en = 1;
                gpio_input_enable(io_num);
            } else {
                gpio_input_disable(io_num);
            }

            if ((pGPIOConfig->mode) & GPIO_MODE_DEF_OD) {
                od_en = 1;
                gpio_od_enable(io_num);
            } else {
                gpio_od_disable(io_num);
            }

            if ((pGPIOConfig->mode) & GPIO_MODE_DEF_OUTPUT) {
                output_en = 1;
                gpio_output_enable(io_num);
            } else {
                gpio_output_disable(io_num);
            }

            if (pGPIOConfig->pull_up_en) {
                pu_en = 1;
                gpio_pullup_en(io_num);
            } else {
                gpio_pullup_dis(io_num);
            }

            if (pGPIOConfig->pull_down_en) {
                pd_en = 1;
                gpio_pulldown_en(io_num);
            } else {
                gpio_pulldown_dis(io_num);
            }

            ESP_LOGD(GPIO_TAG,
                     "GPIO[%" PRIu32 "]| InputEn: %d| OutputEn: %d| OpenDrain: %d| Pullup: %d| Pulldown: %d",
                     io_num, input_en, output_en, od_en, pu_en, pd_en);

            gpio_hal_func_sel(gpio_context.gpio_hal, io_num, PIN_FUNC_GPIO);
        }

        io_num++;
    } while (io_num < GPIO_PIN_COUNT);

    return ESP_OK;
}

esp_err_t gpio_config_as_analog(gpio_num_t gpio_num)
{
    GPIO_CHECK(GPIO_IS_VALID_GPIO(gpio_num), "GPIO number error", ESP_ERR_INVALID_ARG);
    gpio_input_disable(gpio_num);
    gpio_output_disable(gpio_num);
    gpio_pullup_dis(gpio_num);
    gpio_pulldown_dis(gpio_num);
    gpio_hal_func_sel(gpio_context.gpio_hal, gpio_num, PIN_FUNC_GPIO);
    return ESP_OK;
}

esp_err_t gpio_reset_pin(gpio_num_t gpio_num)
{
    assert(GPIO_IS_VALID_GPIO(gpio_num));
    gpio_config_t cfg = {
        .pin_bit_mask = BIT64(gpio_num),
        .mode = GPIO_MODE_DISABLE,
        // for powersave reasons, the GPIO should not be floating, select pullup
        .pull_up_en = true,
        .pull_down_en = false,
    };
    gpio_config(&cfg);
    return ESP_OK;
}

void lp_wdt_init(uint32_t timeout_us)
{
    uint32_t timeout_ticks = (uint32_t)((uint64_t)timeout_us * LP_SLOW_CLK_FREQ_HZ / 1000000);

    lpwdt_ll_write_protect_disable(&LP_WDT);
    lpwdt_ll_disable(&LP_WDT);

    lpwdt_ll_config_stage(&LP_WDT, WDT_STAGE0, timeout_ticks, WDT_STAGE_ACTION_RESET_SYSTEM);
    lpwdt_ll_disable_stage(&LP_WDT, WDT_STAGE1);
    lpwdt_ll_disable_stage(&LP_WDT, WDT_STAGE2);
    lpwdt_ll_disable_stage(&LP_WDT, WDT_STAGE3);

    lpwdt_ll_set_flashboot_en(&LP_WDT, false);
    lpwdt_ll_set_pause_in_sleep_en(&LP_WDT, false);

    lpwdt_ll_enable(&LP_WDT);
    lpwdt_ll_feed(&LP_WDT);
    lpwdt_ll_write_protect_enable(&LP_WDT);
}

void lp_wdt_feed(void)
{
    lpwdt_ll_write_protect_disable(&LP_WDT);
    lpwdt_ll_feed(&LP_WDT);
    lpwdt_ll_write_protect_enable(&LP_WDT);
}

void lp_wdt_disable(void)
{
    lpwdt_ll_write_protect_disable(&LP_WDT);
    lpwdt_ll_disable(&LP_WDT);
    lpwdt_ll_write_protect_enable(&LP_WDT);
}

void wdt_windowed_underflow_callback(void *arg)
{
    (void)arg;

    /* Set window flag to allow feeding */
    wdt_ctx.window_open_flag = true;
}

void wdt_deinit(void)
{
    wdt_hal_write_protect_disable(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_disable(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_write_protect_enable(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_deinit(&wdt_ctx.wdt_hal_ctx);
}

int wdt_init(uint32_t timeout_us)
{
    if (timeout_us < MWDT_DEFAULT_TICKS_PER_US) {
        ESP_LOGE(TAG, "Timeout %lu us too small (minimum %lu us)",
                 (unsigned long)timeout_us, (unsigned long)MWDT_DEFAULT_TICKS_PER_US);
        return -1;
    }

    uint32_t stage_timeout_ticks = timeout_us / MWDT_DEFAULT_TICKS_PER_US;

    ESP_LOGI(TAG, "Enabling WDT(%lu us)", (unsigned long)timeout_us);
    ESP_LOGI(TAG, "WDT prescaler: %u", MWDT_LL_DEFAULT_CLK_PRESCALER);
    ESP_LOGI(TAG, "Stage timeout ticks: %u", stage_timeout_ticks);

    /* Without its bus clock, MWDT register writes are silently dropped and the
     * watchdog never counts. The clock is on at reset, but esp_perip_clk_init()
     * gates it again on some SoCs (ESP32-P4). BIST is the only TIMG0 user, so
     * ungate unconditionally instead of reference counting. */
    PERIPH_RCC_ATOMIC() {
        _timg_ll_enable_bus_clock(MWDT_TIMER_GROUP, true);
        _timg_ll_reset_register(MWDT_TIMER_GROUP);
    }

    esp_cpu_intr_disable(1 << ETS_INT_WDT_INUM);
    esp_rom_route_intr_matrix(esp_cpu_get_core_id(), SYS_TG0_WDT_INTR_SOURCE, ETS_INT_WDT_INUM);

    esp_cpu_intr_set_type(ETS_INT_WDT_INUM, 0);
    esp_cpu_intr_set_priority(ETS_INT_WDT_INUM, SOC_INTERRUPT_LEVEL_MEDIUM);
    esp_cpu_intr_set_handler(ETS_INT_WDT_INUM, mwdt_default_callback, NULL);
    esp_cpu_intr_enable(1 << ETS_INT_WDT_INUM);

    wdt_hal_init(&wdt_ctx.wdt_hal_ctx, WDT_MWDT0, MWDT_LL_DEFAULT_CLK_PRESCALER, true);
    wdt_hal_write_protect_disable(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_config_stage(&wdt_ctx.wdt_hal_ctx, WDT_STAGE0, stage_timeout_ticks, WDT_STAGE_ACTION_INT);
    wdt_hal_config_stage(&wdt_ctx.wdt_hal_ctx, WDT_STAGE1, stage_timeout_ticks * 2, WDT_STAGE_ACTION_RESET_SYSTEM);
    wdt_hal_enable(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_write_protect_enable(&wdt_ctx.wdt_hal_ctx);

    return 0;
}

void wdt_feed(void)
{
    if (wdt_ctx.stop_feed) {
        return;
    }

    if (wdt_ctx.is_windowed && !wdt_ctx.window_open_flag) {
        ESP_LOGE(TAG, "WDT underflow detected: feeding is not allowed (min required = %u us)",
                 wdt_ctx.underflow_timeout);
        wdt_ctx.stop_feed = true;
        return;
    }

    wdt_hal_write_protect_disable(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_feed(&wdt_ctx.wdt_hal_ctx);
    wdt_hal_write_protect_enable(&wdt_ctx.wdt_hal_ctx);

    if (wdt_ctx.is_windowed) {
        wdt_ctx.window_open_flag = false;
        /* Stop timer if running, then start fresh */
        esp_timer_stop(periodic_timer);  /* Ignore error if not running */
        esp_err_t ret = esp_timer_start_once(periodic_timer, wdt_ctx.underflow_timeout);
        if (ret != ESP_OK && ret != ESP_ERR_INVALID_STATE) {
            ESP_LOGE(TAG, "Failed to start windowed timer: %d", ret);
        }
    }
}

void wdt_windowed_deinit(void)
{
    if (wdt_ctx.is_windowed && periodic_timer != NULL) {
        esp_timer_stop(periodic_timer);
        esp_timer_delete(periodic_timer);
        periodic_timer = NULL;
    }

    wdt_ctx.is_windowed = false;
    wdt_ctx.underflow_timeout = 0;
    wdt_ctx.window_open_flag = false;
    wdt_ctx.stop_feed = false;
}

bool wdt_is_underflow_detected(void)
{
    return wdt_ctx.stop_feed;
}

int wdt_init_windowed(uint32_t underflow_timeout_us)
{
    if (underflow_timeout_us == 0) {
        ESP_LOGE(TAG, "Underflow timeout cannot be 0");
        return -1;
    }

    wdt_ctx.is_windowed = true;
    wdt_ctx.underflow_timeout = underflow_timeout_us;

    /* Initialize esp_timer library first (idempotent - safe to call multiple times) */
    esp_err_t ret = esp_timer_init();
    if (ret != ESP_OK && ret != ESP_ERR_INVALID_STATE) {
        ESP_LOGE(TAG, "Failed to initialize esp_timer: %d", ret);
        return -1;
    }

    /* Create timer with proper arguments */
    const esp_timer_create_args_t periodic_timer_args = {
        .callback = wdt_windowed_underflow_callback,
        .arg = NULL,
        .dispatch_method = ESP_TIMER_ISR,
        .name = "wdt_windowed",
        .skip_unhandled_events = false,
    };
    ret = esp_timer_create(&periodic_timer_args, &periodic_timer);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "Failed to create periodic timer: %d", ret);
        return -1;
    }

    ESP_LOGI(TAG, "WDT windowed mode initialized");

    /* Initialize window as open to allow first feed */
    wdt_ctx.window_open_flag = true;

    /* Start the timer */
    ret = esp_timer_start_once(periodic_timer, wdt_ctx.underflow_timeout);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "Failed to start windowed timer: %d", ret);
        return -1;
    }

    return 0;
}

esp_err_t esp_xt_wdt_init(const esp_xt_wdt_config_t *cfg)
{
    xt_wdt_hal_config_t hal_config = {
        .timeout = cfg->timeout,
    };

    xt_wdt_hal_init(&s_hal_ctx, &hal_config);

    if (cfg->auto_backup_clk_enable) {
        /* Estimate frequency of internal RTC oscillator */
        uint32_t rtc_clk_frequency_khz = rtc_clk_freq_cal(rtc_clk_cal(CLK_CAL_RC_SLOW, RTC_CLK_CAL_CYCLES)) / 1000;
        ESP_LOGD(TAG, "Calibrating backup clock from rtc clock with frequency %" PRIu32, rtc_clk_frequency_khz);

        xt_wdt_hal_enable_backup_clk(&s_hal_ctx, rtc_clk_frequency_khz);
    }

    esp_cpu_intr_disable(1 << ETS_RTC_CORE_INTR_SOURCE);
    esp_rom_route_intr_matrix(esp_cpu_get_core_id(), ETS_RTC_CORE_INTR_SOURCE, ETS_RTC_CORE_INTR_SOURCE);

    esp_cpu_intr_set_type(ETS_RTC_CORE_INTR_SOURCE, 0);
    esp_cpu_intr_set_priority(ETS_RTC_CORE_INTR_SOURCE, SOC_INTERRUPT_LEVEL_MEDIUM);
    esp_cpu_intr_set_handler(ETS_RTC_CORE_INTR_SOURCE, rtc_xt_wdt_default_isr_handler, NULL);
    esp_cpu_intr_enable(1 << ETS_RTC_CORE_INTR_SOURCE);

    xt_wdt_hal_enable(&s_hal_ctx, 1);

    return ESP_OK;
}

void esp_xt_wdt_restore_clk(void)
{
    xt_wdt_hal_enable(&s_hal_ctx, false);

    REG_CLR_BIT(RTC_CNTL_EXT_XTL_CONF_REG, RTC_CNTL_XPD_XTAL_32K);
    REG_SET_BIT(RTC_CNTL_EXT_XTL_CONF_REG, RTC_CNTL_XPD_XTAL_32K);

    /* Needs some time after switching to 32khz XTAL before turning on WDT again */
    esp_rom_delay_us(300);

    xt_wdt_hal_enable(&s_hal_ctx, true);
}

void esp_xt_wdt_register_callback(esp_xt_callback_t func, void *arg)
{
    s_callback_func = func;
    s_callback_arg = arg;
}
